package com.fasterxml.jackson.core.io;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for NumberInput.parseBigDecimal(char[] buffer, int offset, int len)
 */
public class NumberInput_parseBigDecimal_TriageGen0Test {

    @Test
    public void testParseBigDecimal_PositiveInteger() throws NumberFormatException {
        char[] buffer = {'1', '2', '3'};
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 3);
        assertEquals(new BigDecimal("123"), result);
    }

    @Test
    public void testParseBigDecimal_NegativeInteger() throws NumberFormatException {
        char[] buffer = {'-', '4', '5', '6'};
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 4);
        assertEquals(new BigDecimal("-456"), result);
    }

    @Test
    public void testParseBigDecimal_WithOffset() throws NumberFormatException {
        char[] buffer = {'a', '1', '.', '2', '5', 'b'};
        // Parse "1.25" which starts at index 1 and has length 4
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 1, 4);
        assertEquals(new BigDecimal("1.25"), result);
    }

    @Test
    public void testParseBigDecimal_Decimal() throws NumberFormatException {
        char[] buffer = {'0', '.', '0', '0', '1'};
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 5);
        assertEquals(new BigDecimal("0.001"), result);
    }

    @Test
    public void testParseBigDecimal_ScientificNotation() throws NumberFormatException {
        char[] buffer = {'1', '.', '2', 'E', '3'};
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 5);
        // 1.2 * 10^3 = 1200
        assertEquals(new BigDecimal("1200"), result.stripTrailingZeros());
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_InvalidCharacters() throws NumberFormatException {
        char[] buffer = {'1', '2', 'a', '4'};
        NumberInput.parseBigDecimal(buffer, 0, 4);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_EmptyRange() throws NumberFormatException {
        char[] buffer = {'1', '2', '3'};
        NumberInput.parseBigDecimal(buffer, 0, 0);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_OnlySign() throws NumberFormatException {
        char[] buffer = {'-'};
        NumberInput.parseBigDecimal(buffer, 0, 1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testParseBigDecimal_OutOfBoundsOffset() throws NumberFormatException {
        char[] buffer = {'1', '2'};
        NumberInput.parseBigDecimal(buffer, 5, 1);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testParseBigDecimal_OutOfBoundsLen() throws NumberFormatException {
        char[] buffer = {'1', '2'};
        NumberInput.parseBigDecimal(buffer, 0, 5);
    }

    @Test
    public void testParseBigDecimal_LargeValue() throws NumberFormatException {
        char[] buffer = {'9', '9', '9', '9', '9', '9', '9', '9', '9', '9', '9', '9'};
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 12);
        assertEquals(new BigDecimal("999999999999"), result);
    }

    @Test
    public void testParseBigDecimal_Zero() throws NumberFormatException {
        char[] buffer = {'0', '0', '.', '0'};
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 4);
        assertEquals(0, result.compareTo(BigDecimal.ZERO));
    }
}
